//www.onetonline.org/link/summary/27-4031.00"},{"text":"Operate television or motion picture cameras to record scenes for television broadcasts, advertising, or motion pictures.","source":"https://www.onetonline.org/link/summary/27-4031.00"},{"text":"Edit video for broadcast productions, including non-linear editing.","source":"https://www.onetonline.org/link/summary/27-4031.00"}],"knowledge":["English Language","Computers and Electronics","Communications and Media","Telecommunications"],"skills":["Active Listening","Reading Comprehension","Speaking","Coordination"],"abilities":["Far Vision","Near Vision","Visualization"],"sources":[{"url":"https://www.onetonline.org/link/summary/27-4031.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29101100","title":"Chiropractors","soc":"29-1011.00","summary":"Assess, treat, and care for patients by manipulation of spine and musculoskeletal system. May provide spinal adjustment or address sacral or pelvic misalignment.","url":"https://www.onetonline.org/link/summary/29-1011.00","sourceURL":"https://www.onetonline.org/link/summary/29-1011.00","vector":[5.53,4.77,1.34,5.56,2.13,3.55],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Perform a series of manual adjustments to the spine or other articulations of the body to correct the musculoskeletal system.","source":"https://www.onetonline.org/link/summary/29-1011.00"},{"text":"Obtain and record patients' medical histories.","source":"https://www.onetonline.org/link/summary/29-1011.00"},{"text":"Diagnose health problems by reviewing patients' health and medical histories, questioning, observing, and examining patients and interpreting x-rays.","source":"https://www.onetonline.org/link/summary/29-1011.00"}],"knowledge":["Medicine and Dentistry","Customer and Personal Service","Biology","Therapy and Counseling"],"skills":["Active Listening","Speaking","Critical Thinking","Reading Comprehension"],"abilities":["Written Comprehension","Deductive Reasoning","Inductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1011.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29102200","title":"Oral and Maxillofacial Surgeons","soc":"29-1022.00","summary":"Perform surgery and related procedures on the hard and soft tissues of the oral and maxillofacial regions to treat diseases, injuries, or defects. May diagnose problems of the oral and maxillofacial regions. May perform surgery to improve function or appearance.","url":"https://www.onetonline.org/link/summary/29-1022.00","sourceURL":"https://www.onetonline.org/link/summary/29-1022.00","vector":[5.75,5.84,1.17,4.47,2.17,3.6],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Administer general and local anesthetics.","source":"https://www.onetonline.org/link/summary/29-1022.00"},{"text":"Remove impacted, damaged, and non-restorable teeth.","source":"https://www.onetonline.org/link/summary/29-1022.00"},{"text":"Evaluate the position of the wisdom teeth to determine whether problems exist currently or might occur in the future.","source":"https://www.onetonline.org/link/summary/29-1022.00"}],"knowledge":["Medicine and Dentistry","Biology","Education and Training","English Language"],"skills":["Critical Thinking","Complex Problem Solving","Active Listening","Reading Comprehension"],"abilities":["Arm-Hand Steadiness","Finger Dexterity","Inductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1022.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29102300","title":"Orthodontists","soc":"29-1023.00","summary":"Examine, diagnose, and treat dental malocclusions and oral cavity anomalies. Design and fabricate appliances to realign teeth and jaws to produce and maintain normal function and to improve appearance.","url":"https://www.onetonline.org/link/summary/29-1023.00","sourceURL":"https://www.onetonline.org/link/summary/29-1023.00","vector":[5.6,5.72,1.57,4.01,1.45,4.58],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Diagnose teeth and jaw or other dental-facial abnormalities.","source":"https://www.onetonline.org/link/summary/29-1023.00"},{"text":"Examine patients to assess abnormalities of jaw development, tooth position, and other dental-facial structures.","source":"https://www.onetonline.org/link/summary/29-1023.00"},{"text":"Study diagnostic records, such as medical or dental histories, plaster models of the teeth, photos of a patient's face and teeth, and X-rays, to develop patient treatment plans.","source":"https://www.onetonline.org/link/summary/29-1023.00"}],"knowledge":["Medicine and Dentistry","Customer and Personal Service","English Language","Biology"],"skills":["Active Listening","Critical Thinking","Monitoring","Speaking"],"abilities":["Problem Sensitivity","Arm-Hand Steadiness","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1023.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29102400","title":"Prosthodontists","soc":"29-1024.00","summary":"Diagnose, treat, rehabilitate, design, and fit prostheses that maintain oral function, health, and appearance for patients with clinical conditions associated with teeth, oral and maxillofacial tissues, or the jaw.","url":"https://www.onetonline.org/link/summary/29-1024.00","sourceURL":"https://www.onetonline.org/link/summary/29-1024.00","vector":[6.17,5.54,1.78,4.59,1.43,3.22],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Examine patients to diagnose oral health conditions and diseases.","source":"https://www.onetonline.org/link/summary/29-1024.00"},{"text":"Fit prostheses to patients, making any necessary adjustments and modifications.","source":"https://www.onetonline.org/link/summary/29-1024.00"},{"text":"Replace missing teeth and associated oral structures with permanent fixtures, such as implant-supported prostheses, crowns and bridges, or removable fixtures, such as dentures.","source":"https://www.onetonline.org/link/summary/29-1024.00"}],"knowledge":["Medicine and Dentistry","Customer and Personal Service","Administration and Management","English Language"],"skills":["Active Listening","Critical Thinking","Speaking","Complex Problem Solving"],"abilities":["Near Vision","Problem Sensitivity","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1024.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29102900","title":"Dentists, All Other Specialists","soc":"29-1029.00","summary":"All dentists not listed separately.","url":"https://www.onetonline.org/link/summary/29-1029.00","sourceURL":"https://www.onetonline.org/link/summary/29-1029.00","vector":null,"expandedDegree":true,"fieldIds":["science"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":null,"tasks":[],"knowledge":[],"skills":[],"abilities":[],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1029.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29104100","title":"Optometrists","soc":"29-1041.00","summary":"Diagnose, manage, and treat conditions and diseases of the human eye and visual system. Examine eyes and visual system, diagnose problems or impairments, prescribe corrective lenses, and provide treatment. May prescribe therapeutic drugs to treat specific eye conditions.","url":"https://www.onetonline.org/link/summary/29-1041.00","sourceURL":"https://www.onetonline.org/link/summary/29-1041.00","vector":[4.8,5.78,1.6,5.02,2.27,3.92],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Examine eyes, using observation, instruments, and pharmaceutical agents, to determine visual acuity and perception, focus, and coordination and to diagnose diseases and other abnormalities, such as glaucoma or color blindness.","source":"https://www.onetonline.org/link/summary/29-1041.00"},{"text":"Analyze test results and develop a treatment plan.","source":"https://www.onetonline.org/link/summary/29-1041.00"},{"text":"Prescribe, supply, fit and adjust eyeglasses, contact lenses, and other vision aids.","source":"https://www.onetonline.org/link/summary/29-1041.00"}],"knowledge":["Medicine and Dentistry","Biology","Customer and Personal Service","English Language"],"skills":["Active Listening","Critical Thinking","Reading Comprehension","Speaking"],"abilities":["Oral Expression","Problem Sensitivity","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1041.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29107101","title":"Anesthesiologist Assistants","soc":"29-1071.01","summary":"Assist anesthesiologists in the administration of anesthesia for surgical and non-surgical procedures. Monitor patient status and provide patient care during surgical treatment.","url":"https://www.onetonline.org/link/summary/29-1071.01","sourceURL":"https://www.onetonline.org/link/summary/29-1071.01","vector":[4.4,4.62,1,4.9,1.89,5.1],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Master's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Provide airway management interventions including tracheal intubation, fiber optics, or ventilary support.","source":"https://www.onetonline.org/link/summary/29-1071.01"},{"text":"Assist anesthesiologists in monitoring of patients, including electrocardiogram (EKG), direct arterial pressure, central venous pressure, arterial blood gas, hematocrit, or routine measurement of temperature, respiration, blood pressure or heart rate.","source":"https://www.onetonline.org/link/summary/29-1071.01"},{"text":"Control anesthesia levels during procedures.","source":"https://www.onetonline.org/link/summary/29-1071.01"}],"knowledge":["Medicine and Dentistry","Biology","English Language","Mathematics"],"skills":["Monitoring","Active Listening","Reading Comprehension","Active Learning"],"abilities":["Oral Comprehension","Problem Sensitivity","Written Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1071.01"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29108100","title":"Podiatrists","soc":"29-1081.00","summary":"Diagnose and treat diseases and deformities of the human foot.","url":"https://www.onetonline.org/link/summary/29-1081.00","sourceURL":"https://www.onetonline.org/link/summary/29-1081.00","vector":[5.29,5.77,1.72,4.94,2.14,3.27],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Treat bone, muscle, and joint disorders affecting the feet and ankles.","source":"https://www.onetonline.org/link/summary/29-1081.00"},{"text":"Diagnose diseases and deformities of the foot using medical histories, physical examinations, x-rays, and laboratory test results.","source":"https://www.onetonline.org/link/summary/29-1081.00"},{"text":"Advise patients about treatments and foot care techniques necessary for prevention of future problems.","source":"https://www.onetonline.org/link/summary/29-1081.00"}],"knowledge":["Medicine and Dentistry","Customer and Personal Service","English Language","Education and Training"],"skills":["Active Learning","Active Listening","Critical Thinking","Reading Comprehension"],"abilities":["Deductive Reasoning","Inductive Reasoning","Problem Sensitivity"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1081.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29112201","title":"Low Vision Therapists, Orientation and Mobility Specialists, and Vision Rehabilitation Therapists","soc":"29-1122.01","summary":"Provide therapy to patients with visual impairments to improve their functioning in daily life activities. May train patients in activities such as computer use, communication skills, or home management skills.","url":"https://www.onetonline.org/link/summary/29-1122.01","sourceURL":"https://www.onetonline.org/link/summary/29-1122.01","vector":[3.93,3.89,3.2,6.52,2.12,2.83],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Master's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Teach cane skills, including cane use with a guide, diagonal techniques, and two-point touches.","source":"https://www.onetonline.org/link/summary/29-1122.01"},{"text":"Recommend appropriate mobility devices or systems, such as human guides, dog guides, long canes, electronic travel aids (ETAs), and other adaptive mobility devices (AMDs).","source":"https://www.onetonline.org/link/summary/29-1122.01"},{"text":"Train clients with visual impairments to use mobility devices or systems, such as human guides, dog guides, electronic travel aids (ETAs), and other adaptive mobility devices (AMDs).","source":"https://www.onetonline.org/link/summary/29-1122.01"}],"knowledge":["English Language","Education and Training","Psychology","Transportation"],"skills":["Active Listening","Learning Strategies","Speaking","Reading Comprehension"],"abilities":["Oral Expression","Oral Comprehension","Problem Sensitivity"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1122.01"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29112500","title":"Recreational Therapists","soc":"29-1125.00","summary":"Plan, direct, or coordinate medically-approved recreation programs for patients in hospitals, nursing homes, or other institutions. Activities include sports, trips, dramatics, social activities, and crafts. May assess a patient condition and recommend appropriate recreational activity.","url":"https://www.onetonline.org/link/summary/29-1125.00","sourceURL":"https://www.onetonline.org/link/summary/29-1125.00","vector":[3.69,4.32,2.87,6.82,2.51,2.67],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Instruct patient in activities and techniques, such as sports, dance, music, art, or relaxation techniques, designed to meet their specific physical or psychological needs.","source":"https://www.onetonline.org/link/summary/29-1125.00"},{"text":"Conduct therapy sessions to improve patients' mental and physical well-being.","source":"https://www.onetonline.org/link/summary/29-1125.00"},{"text":"Plan, organize, direct, and participate in treatment programs and activities to facilitate patients' rehabilitation, help them integrate into the community, and prevent further medical problems.","source":"https://www.onetonline.org/link/summary/29-1125.00"}],"knowledge":["Psychology","Therapy and Counseling","Customer and Personal Service","Education and Training"],"skills":["Service Orientation","Active Listening","Speaking","Coordination"],"abilities":["Oral Comprehension","Oral Expression","Speech Clarity"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1125.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29112900","title":"Therapists, All Other","soc":"29-1129.00","summary":"All therapists not listed separately.","url":"https://www.onetonline.org/link/summary/29-1129.00","sourceURL":"https://www.onetonline.org/link/summary/29-1129.00","vector":null,"expandedDegree":true,"fieldIds":["science"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"college","jobZone":null,"tasks":[],"knowledge":[],"skills":[],"abilities":[],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1129.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29112901","title":"Art Therapists","soc":"29-1129.01","summary":"Plan or conduct art therapy sessions or programs to improve clients' physical, cognitive, or emotional well-being.","url":"https://www.onetonline.org/link/summary/29-1129.01","sourceURL":"https://www.onetonline.org/link/summary/29-1129.01","vector":[2.99,3.67,5.49,5.64,2.32,2.86],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"college","jobZone":5,"tasks":[{"text":"Conduct art therapy sessions, providing guided self-expression experiences to help clients recover from, or cope with, cognitive, emotional, or physical impairments.","source":"https://www.onetonline.org/link/summary/29-1129.01"},{"text":"Talk with clients during art or other therapy sessions to build rapport, acknowledge their progress, or reflect upon their reactions to the artistic process.","source":"https://www.onetonline.org/link/summary/29-1129.01"},{"text":"Write treatment plans, case summaries, or progress or other reports related to individual clients or client groups.","source":"https://www.onetonline.org/link/summary/29-1129.01"}],"knowledge":["Therapy and Counseling","Psychology","Fine Arts","Sociology and Anthropology"],"skills":["Social Perceptiveness","Active Listening","Monitoring","Speaking"],"abilities":["Oral Expression","Inductive Reasoning","Near Vision"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1129.01"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29112902","title":"Music Therapists","soc":"29-1129.02","summary":"Plan, organize, direct, or assess clinical and evidenced-based music therapy interventions to positively influence individuals' physical, psychological, cognitive, or behavioral status.","url":"https://www.onetonline.org/link/summary/29-1129.02","sourceURL":"https://www.onetonline.org/link/summary/29-1129.02","vector":[2.36,4.18,4.76,5.23,2.51,3.15],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Design or provide music therapy experiences to address client needs, such as using music for self-care, adjusting to life changes, improving cognitive functioning, raising self-esteem, communicating, or controlling impulses.","source":"https://www.onetonline.org/link/summary/29-1129.02"},{"text":"Design music therapy experiences, using various musical elements to meet client's goals or objectives.","source":"https://www.onetonline.org/link/summary/29-1129.02"},{"text":"Sing or play musical instruments, such as keyboard, guitar, or percussion instruments.","source":"https://www.onetonline.org/link/summary/29-1129.02"}],"knowledge":["Psychology","Therapy and Counseling","Fine Arts","English Language"],"skills":["Social Perceptiveness","Active Listening","Critical Thinking","Reading Comprehension"],"abilities":["Oral Expression","Problem Sensitivity","Oral Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1129.02"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29114101","title":"Acute Care Nurses","soc":"29-1141.01","summary":"Provide advanced nursing care for patients with acute conditions such as heart attacks, respiratory distress syndrome, or shock. May care for pre- and post-operative patients or perform advanced, invasive diagnostic or therapeutic procedures.","url":"https://www.onetonline.org/link/summary/29-1141.01","sourceURL":"https://www.onetonline.org/link/summary/29-1141.01","vector":[3.7,5.66,1.75,5.8,1.76,3.32],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Discuss illnesses and treatments with patients and family members.","source":"https://www.onetonline.org/link/summary/29-1141.01"},{"text":"Diagnose acute or chronic conditions that could result in rapid physiological deterioration or life-threatening instability.","source":"https://www.onetonline.org/link/summary/29-1141.01"},{"text":"Perform emergency medical procedures, such as basic cardiac life support (BLS), advanced cardiac life support (ACLS), and other condition-stabilizing interventions.","source":"https://www.onetonline.org/link/summary/29-1141.01"}],"knowledge":["Medicine and Dentistry","Customer and Personal Service","Education and Training","English Language"],"skills":["Critical Thinking","Reading Comprehension","Speaking","Service Orientation"],"abilities":["Oral Comprehension","Oral Expression","Problem Sensitivity"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1141.01"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29114102","title":"Advanced Practice Psychiatric Nurses","soc":"29-1141.02","summary":"Assess, diagnose, and treat individuals and families with mental health or substance use disorders or the potential for such disorders. Apply therapeutic activities, including the prescription of medication, per state regulations, and the administration of psychotherapy.","url":"https://www.onetonline.org/link/summary/29-1141.02","sourceURL":"https://www.onetonline.org/link/summary/29-1141.02","vector":[2.59,5.9,2.82,6.07,2.04,3.35],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"college","jobZone":5,"tasks":[{"text":"Assess patients' mental and physical status, based on the presenting symptoms and complaints.","source":"https://www.onetonline.org/link/summary/29-1141.02"},{"text":"Diagnose psychiatric disorders and mental health conditions.","source":"https://www.onetonline.org/link/summary/29-1141.02"},{"text":"Document patients' medical and psychological histories, physical assessment results, diagnoses, treatment plans, prescriptions, or outcomes.","source":"https://www.onetonline.org/link/summary/29-1141.02"}],"knowledge":["Psychology","Therapy and Counseling","English Language","Medicine and Dentistry"],"skills":["Active Listening","Social Perceptiveness","Speaking","Critical Thinking"],"abilities":["Problem Sensitivity","Oral Comprehension","Oral Expression"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1141.02"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29114103","title":"Critical Care Nurses","soc":"29-1141.03","summary":"Provide specialized nursing care for patients in critical or coronary care units.","url":"https://www.onetonline.org/link/summary/29-1141.03","sourceURL":"https://www.onetonline.org/link/summary/29-1141.03","vector":[3.91,5.02,1.7,5.56,2.2,4.23],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Evaluate patients' vital signs or laboratory data to determine emergency intervention needs.","source":"https://www.onetonline.org/link/summary/29-1141.03"},{"text":"Monitor patients for changes in status and indications of conditions such as sepsis or shock and institute appropriate interventions.","source":"https://www.onetonline.org/link/summary/29-1141.03"},{"text":"Administer medications intravenously, by injection, orally, through gastric tubes, or by other methods.","source":"https://www.onetonline.org/link/summary/29-1141.03"}],"knowledge":["Medicine and Dentistry","Customer and Personal Service","English Language","Psychology"],"skills":["Monitoring","Active Listening","Critical Thinking","Reading Comprehension"],"abilities":["Oral Comprehension","Problem Sensitivity","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1141.03"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29114104","title":"Clinical Nurse Specialists","soc":"29-1141.04","summary":"Direct nursing staff in the provision of patient care in a clinical practice setting, such as a hospital, hospice, clinic, or home. Ensure adherence to established clinical policies, protocols, regulations, and standards.","url":"https://www.onetonline.org/link/summary/29-1141.04","sourceURL":"https://www.onetonline.org/link/summary/29-1141.04","vector":[2.34,4.86,1.81,6.23,3.69,4.04],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"college","jobZone":5,"tasks":[{"text":"Provide specialized direct and indirect care to inpatients and outpatients within a designated specialty, such as obstetrics, neurology, oncology, or neonatal care.","source":"https://www.onetonline.org/link/summary/29-1141.04"},{"text":"Collaborate with other health care professionals and service providers to ensure optimal patient care.","source":"https://www.onetonline.org/link/summary/29-1141.04"},{"text":"Read current literature, talk with colleagues, or participate in professional organizations or conferences to keep abreast of developments in nursing.","source":"https://www.onetonline.org/link/summary/29-1141.04"}],"knowledge":["Medicine and Dentistry","Education and Training","English Language","Psychology"],"skills":["Speaking","Active Learning","Critical Thinking","Monitoring"],"abilities":["Oral Comprehension","Oral Expression","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1141.04"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29115100","title":"Nurse Anesthetists","soc":"29-1151.00","summary":"Administer anesthesia, monitor patient's vital signs, and oversee patient recovery from anesthesia. May assist anesthesiologists, surgeons, other physicians, or dentists. Must be registered nurses who have specialized graduate education.","url":"https://www.onetonline.org/link/summary/29-1151.00","sourceURL":"https://www.onetonline.org/link/summary/29-1151.00","vector":[4.78,5.06,1,5.35,1.96,4.15],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Master's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Manage patients' airway or pulmonary status, using techniques such as endotracheal intubation, mechanical ventilation, pharmacological support, respiratory therapy, and extubation.","source":"https://www.onetonline.org/link/summary/29-1151.00"},{"text":"Respond to emergency situations by providing airway management, administering emergency fluids or drugs, or using basic or advanced cardiac life support techniques.","source":"https://www.onetonline.org/link/summary/29-1151.00"},{"text":"Monitor patients' responses, including skin color, pupil dilation, pulse, heart rate, blood pressure, respiration, ventilation, or urine output, using invasive and noninvasive techniques.","source":"https://www.onetonline.org/link/summary/29-1151.00"}],"knowledge":["Medicine and Dentistry","Biology","Customer and Personal Service","Chemistry"],"skills":["Critical Thinking","Reading Comprehension","Active Learning","Active Listening"],"abilities":["Problem Sensitivity","Information Ordering","Oral Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1151.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29116100","title":"Nurse Midwives","soc":"29-1161.00","summary":"Diagnose and coordinate all aspects of the birthing process, either independently or as part of a healthcare team. May provide well-woman gynecological care. Must have specialized, graduate nursing education.","url":"https://www.onetonline.org/link/summary/29-1161.00","sourceURL":"https://www.onetonline.org/link/summary/29-1161.00","vector":[3.24,4.25,1.94,5.96,2.97,3.4],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Master's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Provide prenatal, intrapartum, postpartum, or newborn care to patients.","source":"https://www.onetonline.org/link/summary/29-1161.00"},{"text":"Monitor fetal development by listening to fetal heartbeat, taking external uterine measurements, identifying fetal position, or estimating fetal size and weight.","source":"https://www.onetonline.org/link/summary/29-1161.00"},{"text":"Document patients' health histories, symptoms, physical conditions, or other diagnostic information.","source":"https://www.onetonline.org/link/summary/29-1161.00"}],"knowledge":["Medicine and Dentistry","Psychology","Customer and Personal Service","English Language"],"skills":["Active Listening","Critical Thinking","Speaking","Social Perceptiveness"],"abilities":["Written Comprehension","Deductive Reasoning","Oral Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1161.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29118100","title":"Audiologists","soc":"29-1181.00","summary":"Assess and treat persons with hearing and related disorders. May fit hearing aids and provide auditory training. May perform research related to hearing problems.","url":"https://www.onetonline.org/link/summary/29-1181.00","sourceURL":"https://www.onetonline.org/link/summary/29-1181.00","vector":[3.98,5.93,2.18,5.92,1.81,3.97],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Maintain patient records at all stages, including initial and subsequent evaluation and treatment activities.","source":"https://www.onetonline.org/link/summary/29-1181.00"},{"text":"Evaluate hearing and balance disorders to determine diagnoses and courses of treatment.","source":"https://www.onetonline.org/link/summary/29-1181.00"},{"text":"Fit, dispense, and repair assistive devices, such as hearing aids.","source":"https://www.onetonline.org/link/summary/29-1181.00"}],"knowledge":["Customer and Personal Service","Therapy and Counseling","Psychology","Medicine and Dentistry"],"skills":["Active Listening","Reading Comprehension","Active Learning","Critical Thinking"],"abilities":["Oral Comprehension","Written Comprehension","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1181.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29121100","title":"Anesthesiologists","soc":"29-1211.00","summary":"Administer anesthetics and analgesics for pain management prior to, during, or after surgery.","url":"https://www.onetonline.org/link/summary/29-1211.00","sourceURL":"https://www.onetonline.org/link/summary/29-1211.00","vector":[5.18,5.73,1.17,5.25,2.5,3.69],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Examine patient, obtain medical history, and use diagnostic tests to determine risk during surgical, obstetrical, and other medical procedures.","source":"https://www.onetonline.org/link/summary/29-1211.00"},{"text":"Administer anesthetic or sedation during medical procedures, using local, intravenous, spinal, or caudal methods.","source":"https://www.onetonline.org/link/summary/29-1211.00"},{"text":"Record type and amount of anesthesia and patient condition throughout procedure.","source":"https://www.onetonline.org/link/summary/29-1211.00"}],"knowledge":["English Language","Biology","Psychology","Mathematics"],"skills":["Critical Thinking","Judgment and Decision Making","Monitoring","Reading Comprehension"],"abilities":["Problem Sensitivity","Deductive Reasoning","Oral Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1211.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29121200","title":"Cardiologists","soc":"29-1212.00","summary":"Diagnose, treat, manage, and prevent diseases or conditions of the cardiovascular system. May further subspecialize in interventional procedures (e.g., balloon angioplasty and stent placement), echocardiography, or electrophysiology.","url":"https://www.onetonline.org/link/summary/29-1212.00","sourceURL":"https://www.onetonline.org/link/summary/29-1212.00","vector":[4.96,6.87,1.15,4.73,2.28,4],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Administer emergency cardiac care for life-threatening heart problems, such as cardiac arrest and heart attack.","source":"https://www.onetonline.org/link/summary/29-1212.00"},{"text":"Advise patients and community members concerning diet, activity, hygiene, or disease prevention.","source":"https://www.onetonline.org/link/summary/29-1212.00"},{"text":"Answer questions that patients have about their health and well-being.","source":"https://www.onetonline.org/link/summary/29-1212.00"}],"knowledge":[],"skills":[],"abilities":[],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1212.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29121300","title":"Dermatologists","soc":"29-1213.00","summary":"Diagnose and treat diseases relating to the skin, hair, and nails. May perform both medical and dermatological surgery functions.","url":"https://www.onetonline.org/link/summary/29-1213.00","sourceURL":"https://www.onetonline.org/link/summary/29-1213.00","vector":[4.81,6.44,1.87,4.65,1.77,3.83],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Conduct complete skin examinations.","source":"https://www.onetonline.org/link/summary/29-1213.00"},{"text":"Diagnose and treat pigmented lesions such as common acquired nevi, congenital nevi, dysplastic nevi, Spitz nevi, blue nevi, or melanoma.","source":"https://www.onetonline.org/link/summary/29-1213.00"},{"text":"Perform incisional biopsies to diagnose melanoma.","source":"https://www.onetonline.org/link/summary/29-1213.00"}],"knowledge":["Medicine and Dentistry","Customer and Personal Service","English Language","Administration and Management"],"skills":["Critical Thinking","Active Listening","Service Orientation","Reading Comprehension"],"abilities":["Oral Expression","Problem Sensitivity","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1213.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29121400","title":"Emergency Medicine Physicians","soc":"29-1214.00","summary":"Make immediate medical decisions and act to prevent death or further disability. Provide immediate recognition, evaluation, care, stabilization, and disposition of patients. May direct emergency medical staff in an emergency department.","url":"https://www.onetonline.org/link/summary/29-1214.00","sourceURL":"https://www.onetonline.org/link/summary/29-1214.00","vector":[4.15,5.64,1,5.6,2.68,4.22],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Select, request, perform, or interpret diagnostic procedures, such as laboratory tests, electrocardiograms, emergency ultrasounds, and radiographs.","source":"https://www.onetonline.org/link/summary/29-1214.00"},{"text":"Evaluate patients' vital signs or laboratory data to determine emergency intervention needs and priority of treatment.","source":"https://www.onetonline.org/link/summary/29-1214.00"},{"text":"Perform emergency resuscitations on patients.","source":"https://www.onetonline.org/link/summary/29-1214.00"}],"knowledge":["Medicine and Dentistry","English Language","Biology","Psychology"],"skills":["Active Listening","Critical Thinking","Reading Comprehension","Speaking"],"abilities":["Oral Comprehension","Oral Expression","Written Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1214.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29121600","title":"General Internal Medicine Physicians","soc":"29-1216.00","summary":"Diagnose and provide nonsurgical treatment for a wide range of diseases and injuries of internal organ systems. Provide care mainly for adults and adolescents, and are based primarily in an outpatient care setting.","url":"https://www.onetonline.org/link/summary/29-1216.00","sourceURL":"https://www.onetonline.org/link/summary/29-1216.00","vector":[4.43,6.81,1.44,6.08,2.1,3.63],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Analyze records, reports, test results, or examination information to diagnose medical condition of patient.","source":"https://www.onetonline.org/link/summary/29-1216.00"},{"text":"Treat internal disorders, such as hypertension, heart disease, diabetes, or problems of the lung, brain, kidney, or gastrointestinal tract.","source":"https://www.onetonline.org/link/summary/29-1216.00"},{"text":"Prescribe or administer medication, therapy, and other specialized medical care to treat or prevent illness, disease, or injury.","source":"https://www.onetonline.org/link/summary/29-1216.00"}],"knowledge":["Medicine and Dentistry","Biology","Therapy and Counseling","Psychology"],"skills":["Active Listening","Reading Comprehension","Critical Thinking","Science"],"abilities":["Problem Sensitivity","Inductive Reasoning","Oral Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1216.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29121700","title":"Neurologists","soc":"29-1217.00","summary":"Diagnose, manage, and treat disorders and diseases of the brain, spinal cord, and peripheral nerves, with a primarily nonsurgical focus.","url":"https://www.onetonline.org/link/summary/29-1217.00","sourceURL":"https://www.onetonline.org/link/summary/29-1217.00","vector":[4.1,7,2.08,5.02,2.39,3.69],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Interview patients to obtain information, such as complaints, symptoms, medical histories, and family histories.","source":"https://www.onetonline.org/link/summary/29-1217.00"},{"text":"Examine patients to obtain information about functional status of areas, such as vision, physical strength, coordination, reflexes, sensations, language skills, cognitive abilities, and mental status.","source":"https://www.onetonline.org/link/summary/29-1217.00"},{"text":"Perform or interpret the outcomes of procedures or diagnostic tests, such as lumbar punctures, electroencephalography, electromyography, and nerve conduction velocity tests.","source":"https://www.onetonline.org/link/summary/29-1217.00"}],"knowledge":["Medicine and Dentistry","English Language","Psychology","Biology"],"skills":["Active Listening","Critical Thinking","Reading Comprehension","Speaking"],"abilities":["Inductive Reasoning","Deductive Reasoning","Oral Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1217.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29121800","title":"Obstetricians and Gynecologists","soc":"29-1218.00","summary":"Provide medical care related to pregnancy or childbirth. Diagnose, treat, and help prevent diseases of women, particularly those affecting the reproductive system. May also provide general care to women. May perform both medical and gynecological surgery functions.","url":"https://www.onetonline.org/link/summary/29-1218.00","sourceURL":"https://www.onetonline.org/link/summary/29-1218.00","vector":[4.59,5.5,1.45,5.45,2.74,3.72],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Treat diseases of female organs.","source":"https://www.onetonline.org/link/summary/29-1218.00"},{"text":"Care for and treat women during prenatal, natal, and postnatal periods.","source":"https://www.onetonline.org/link/summary/29-1218.00"},{"text":"Analyze records, reports, test results, or examination information to diagnose medical condition of patient.","source":"https://www.onetonline.org/link/summary/29-1218.00"}],"knowledge":["Medicine and Dentistry","Biology","English Language","Psychology"],"skills":["Critical Thinking","Reading Comprehension","Active Learning","Active Listening"],"abilities":["Problem Sensitivity","Inductive Reasoning","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1218.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29122100","title":"Pediatricians, General","soc":"29-1221.00","summary":"Diagnose, treat, and help prevent diseases and injuries in children. May refer patients to specialists for further diagnosis or treatment, as needed.","url":"https://www.onetonline.org/link/summary/29-1221.00","sourceURL":"https://www.onetonline.org/link/summary/29-1221.00","vector":[3.64,6.18,1.88,6.64,2.54,3.58],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Prescribe or administer treatment, therapy, medication, vaccination, and other specialized medical care to treat or prevent illness, disease, or injury in infants and children.","source":"https://www.onetonline.org/link/summary/29-1221.00"},{"text":"Examine children regularly to assess their growth and development.","source":"https://www.onetonline.org/link/summary/29-1221.00"},{"text":"Treat children who have minor illnesses, acute and chronic health problems, and growth and development concerns.","source":"https://www.onetonline.org/link/summary/29-1221.00"}],"knowledge":["Medicine and Dentistry","Therapy and Counseling","Biology","Psychology"],"skills":["Critical Thinking","Speaking","Judgment and Decision Making","Active Listening"],"abilities":["Oral Comprehension","Oral Expression","Inductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1221.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29122200","title":"Physicians, Pathologists","soc":"29-1222.00","summary":"Diagnose diseases and conduct lab tests using organs, body tissues, and fluids. Includes medical examiners.","url":"https://www.onetonline.org/link/summary/29-1222.00","sourceURL":"https://www.onetonline.org/link/summary/29-1222.00","vector":[4.86,7,1.36,3.6,1.76,4.72],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Examine microscopic samples to identify diseases or other abnormalities.","source":"https://www.onetonline.org/link/summary/29-1222.00"},{"text":"Diagnose diseases or study medical conditions, using techniques such as gross pathology, histology, cytology, cytopathology, clinical chemistry, immunology, flow cytometry, or molecular biology.","source":"https://www.onetonline.org/link/summary/29-1222.00"},{"text":"Write pathology reports summarizing analyses, results, and conclusions.","source":"https://www.onetonline.org/link/summary/29-1222.00"}],"knowledge":["Medicine and Dentistry","Biology","English Language","Education and Training"],"skills":["Reading Comprehension","Critical Thinking","Writing","Active Learning"],"abilities":["Inductive Reasoning","Problem Sensitivity","Oral Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1222.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29122300","title":"Psychiatrists","soc":"29-1223.00","summary":"Diagnose, treat, and help prevent mental disorders.","url":"https://www.onetonline.org/link/summary/29-1223.00","sourceURL":"https://www.onetonline.org/link/summary/29-1223.00","vector":[2.3,6.59,2.65,5.83,1.95,3.6],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Prescribe, direct, or administer psychotherapeutic treatments or medications to treat mental, emotional, or behavioral disorders.","source":"https://www.onetonline.org/link/summary/29-1223.00"},{"text":"Gather and maintain patient information and records, including social or medical history obtained from patients, relatives, or other professionals.","source":"https://www.onetonline.org/link/summary/29-1223.00"},{"text":"Collaborate with physicians, psychologists, social workers, psychiatric nurses, or other professionals to discuss treatment plans and progress.","source":"https://www.onetonline.org/link/summary/29-1223.00"}],"knowledge":["Medicine and Dentistry","Therapy and Counseling","Psychology","Biology"],"skills":["Active Listening","Social Perceptiveness","Critical Thinking","Speaking"],"abilities":["Oral Comprehension","Oral Expression","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1223.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29122400","title":"Radiologists","soc":"29-1224.00","summary":"Diagnose and treat diseases and injuries using medical imaging techniques, such as x rays, magnetic resonance imaging (MRI), nuclear medicine, and ultrasounds. May perform minimally invasive medical procedures and tests.","url":"https://www.onetonline.org/link/summary/29-1224.00","sourceURL":"https://www.onetonline.org/link/summary/29-1224.00","vector":[4.89,6.62,1.37,3.85,2.17,4.47],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Prepare comprehensive interpretive reports of findings.","source":"https://www.onetonline.org/link/summary/29-1224.00"},{"text":"Perform or interpret the outcomes of diagnostic imaging procedures including magnetic resonance imaging (MRI), computer tomography (CT), positron emission tomography (PET), nuclear cardiology treadmill studies, mammography, or ultrasound.","source":"https://www.onetonline.org/link/summary/29-1224.00"},{"text":"Document the performance, interpretation, or outcomes of all procedures performed.","source":"https://www.onetonline.org/link/summary/29-1224.00"}],"knowledge":["Medicine and Dentistry","Biology","English Language","Computers and Electronics"],"skills":["Active Listening","Reading Comprehension","Speaking","Critical Thinking"],"abilities":["Inductive Reasoning","Problem Sensitivity","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1224.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29122900","title":"Physicians, All Other","soc":"29-1229.00","summary":"All physicians not listed separately.","url":"https://www.onetonline.org/link/summary/29-1229.00","sourceURL":"https://www.onetonline.org/link/summary/29-1229.00","vector":null,"expandedDegree":true,"fieldIds":["science"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":null,"tasks":[],"knowledge":[],"skills":[],"abilities":[],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1229.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29122901","title":"Allergists and Immunologists","soc":"29-1229.01","summary":"Diagnose, treat, and help prevent allergic diseases and disease processes affecting the immune system.","url":"https://www.onetonline.org/link/summary/29-1229.01","sourceURL":"https://www.onetonline.org/link/summary/29-1229.01","vector":[3.84,6.95,1.85,5.3,2.2,3.67],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Diagnose or treat allergic or immunologic conditions.","source":"https://www.onetonline.org/link/summary/29-1229.01"},{"text":"Educate patients about diagnoses, prognoses, or treatments.","source":"https://www.onetonline.org/link/summary/29-1229.01"},{"text":"Order or perform diagnostic tests such as skin pricks and intradermal, patch, or delayed hypersensitivity tests.","source":"https://www.onetonline.org/link/summary/29-1229.01"}],"knowledge":["Medicine and Dentistry","English Language","Customer and Personal Service","Biology"],"skills":["Reading Comprehension","Active Listening","Critical Thinking","Writing"],"abilities":["Problem Sensitivity","Deductive Reasoning","Oral Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1229.01"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29122902","title":"Hospitalists","soc":"29-1229.02","summary":"Provide inpatient care predominantly in settings such as medical wards, acute care units, intensive care units, rehabilitation centers, or emergency rooms. Manage and coordinate patient care throughout treatment.","url":"https://www.onetonline.org/link/summary/29-1229.02","sourceURL":"https://www.onetonline.org/link/summary/29-1229.02","vector":[3.55,4.58,1.64,6.27,3.14,3.9],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Diagnose, treat, or provide continuous care to hospital inpatients.","source":"https://www.onetonline.org/link/summary/29-1229.02"},{"text":"Prescribe medications or treatment regimens to hospital inpatients.","source":"https://www.onetonline.org/link/summary/29-1229.02"},{"text":"Order or interpret the results of tests such as laboratory tests and radiographs (x-rays).","source":"https://www.onetonline.org/link/summary/29-1229.02"}],"knowledge":["Medicine and Dentistry","Biology","English Language","Psychology"],"skills":["Active Learning","Active Listening","Critical Thinking","Reading Comprehension"],"abilities":["Inductive Reasoning","Oral Comprehension","Oral Expression"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1229.02"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29122903","title":"Urologists","soc":"29-1229.03","summary":"Diagnose, treat, and help prevent benign and malignant medical and surgical disorders of the genitourinary system and the renal glands.","url":"https://www.onetonline.org/link/summary/29-1229.03","sourceURL":"https://www.onetonline.org/link/summary/29-1229.03","vector":[4.85,6.85,1.31,5.45,2.22,3.43],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Diagnose or treat diseases or disorders of genitourinary organs and tracts including erectile dysfunction (ED), infertility, incontinence, bladder cancer, prostate cancer, urethral stones, or premature ejaculation.","source":"https://www.onetonline.org/link/summary/29-1229.03"},{"text":"Examine patients using equipment, such as radiograph (x-ray) machines or fluoroscopes, to determine the nature and extent of disorder or injury.","source":"https://www.onetonline.org/link/summary/29-1229.03"},{"text":"Order and interpret the results of diagnostic tests, such as prostate specific antigen (PSA) screening, to detect prostate cancer.","source":"https://www.onetonline.org/link/summary/29-1229.03"}],"knowledge":["Medicine and Dentistry","Biology","English Language","Education and Training"],"skills":["Reading Comprehension","Critical Thinking","Judgment and Decision Making","Active Listening"],"abilities":["Problem Sensitivity","Written Comprehension","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1229.03"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29122904","title":"Physical Medicine and Rehabilitation Physicians","soc":"29-1229.04","summary":"Diagnose and treat disorders requiring physiotherapy to provide physical, mental, and occupational rehabilitation.","url":"https://www.onetonline.org/link/summary/29-1229.04","sourceURL":"https://www.onetonline.org/link/summary/29-1229.04","vector":[4.92,6.26,1.87,6,1.69,3],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Document examination results, treatment plans, and patients' outcomes.","source":"https://www.onetonline.org/link/summary/29-1229.04"},{"text":"Examine patients to assess mobility, strength, communication, or cognition.","source":"https://www.onetonline.org/link/summary/29-1229.04"},{"text":"Develop comprehensive plans for immediate and long-term rehabilitation, including therapeutic exercise, speech and occupational therapy, counseling, cognitive retraining, patient, family or caregiver education, or community reintegration.","source":"https://www.onetonline.org/link/summary/29-1229.04"}],"knowledge":["Medicine and Dentistry","English Language","Psychology","Biology"],"skills":["Critical Thinking","Active Listening","Reading Comprehension","Speaking"],"abilities":["Deductive Reasoning","Inductive Reasoning","Oral Expression"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1229.04"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29122905","title":"Preventive Medicine Physicians","soc":"29-1229.05","summary":"Apply knowledge of general preventive medicine and public health issues to promote health care to groups or individuals, and aid in the prevention or reduction of risk of disease, injury, disability, or death. May practice population-based medicine or diagnose and treat patients in the context of clinical health promotion and disease prevention.","url":"https://www.onetonline.org/link/summary/29-1229.05","sourceURL":"https://www.onetonline.org/link/summary/29-1229.05","vector":[3.37,6.7,1.88,5.43,2.37,3.39],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Direct or manage prevention programs in specialty areas such as aerospace, occupational, infectious disease, and environmental medicine.","source":"https://www.onetonline.org/link/summary/29-1229.05"},{"text":"Document or review comprehensive patients' histories with an emphasis on occupation or environmental risks.","source":"https://www.onetonline.org/link/summary/29-1229.05"},{"text":"Identify groups at risk for specific preventable diseases or injuries.","source":"https://www.onetonline.org/link/summary/29-1229.05"}],"knowledge":["Medicine and Dentistry","Biology","English Language","Education and Training"],"skills":["Reading Comprehension","Active Listening","Critical Thinking","Speaking"],"abilities":["Deductive Reasoning","Inductive Reasoning","Oral Expression"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1229.05"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29122906","title":"Sports Medicine Physicians","soc":"29-1229.06","summary":"Diagnose, treat, and help prevent injuries that occur during sporting events, athletic training, and physical activities.","url":"https://www.onetonline.org/link/summary/29-1229.06","sourceURL":"https://www.onetonline.org/link/summary/29-1229.06","vector":[5.19,5.36,1.2,5.27,3.34,3.52],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Diagnose or treat disorders of the musculoskeletal system.","source":"https://www.onetonline.org/link/summary/29-1229.06"},{"text":"Order and interpret the results of laboratory tests and diagnostic imaging procedures.","source":"https://www.onetonline.org/link/summary/29-1229.06"},{"text":"Record athletes' medical histories, and perform physical examinations.","source":"https://www.onetonline.org/link/summary/29-1229.06"}],"knowledge":["Medicine and Dentistry","Biology","English Language","Therapy and Counseling"],"skills":["Reading Comprehension","Critical Thinking","Judgment and Decision Making","Active Listening"],"abilities":["Oral Comprehension","Oral Expression","Problem Sensitivity"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1229.06"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29124100","title":"Ophthalmologists, Except Pediatric","soc":"29-1241.00","summary":"Diagnose and perform surgery to treat and help prevent disorders and diseases of the eye. May also provide vision services for treatment including glasses and contacts.","url":"https://www.onetonline.org/link/summary/29-1241.00","sourceURL":"https://www.onetonline.org/link/summary/29-1241.00","vector":[4.4,6.24,1.7,5.46,2.98,3.72],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Perform comprehensive examinations of the visual system to determine the nature or extent of ocular disorders.","source":"https://www.onetonline.org/link/summary/29-1241.00"},{"text":"Diagnose or treat injuries, disorders, or diseases of the eye and eye structures including the cornea, sclera, conjunctiva, or eyelids.","source":"https://www.onetonline.org/link/summary/29-1241.00"},{"text":"Provide or direct the provision of postoperative care.","source":"https://www.onetonline.org/link/summary/29-1241.00"}],"knowledge":["Medicine and Dentistry","English Language","Customer and Personal Service","Biology"],"skills":["Critical Thinking","Reading Comprehension","Active Listening","Active Learning"],"abilities":["Inductive Reasoning","Near Vision","Problem Sensitivity"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1241.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29124200","title":"Orthopedic Surgeons, Except Pediatric","soc":"29-1242.00","summary":"Diagnose and perform surgery to treat and prevent rheumatic and other diseases in the musculoskeletal system.","url":"https://www.onetonline.org/link/summary/29-1242.00","sourceURL":"https://www.onetonline.org/link/summary/29-1242.00","vector":[5.08,6.5,1.48,4.82,2.36,3.91],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Analyze patient's medical history, medication allergies, physical condition, and examination results to verify operation's necessity and to determine best procedure.","source":"https://www.onetonline.org/link/summary/29-1242.00"},{"text":"Conduct research to develop and test surgical techniques that can improve operating procedures and outcomes related to musculoskeletal injuries and diseases.","source":"https://www.onetonline.org/link/summary/29-1242.00"},{"text":"Diagnose bodily disorders and orthopedic conditions, and provide treatments, such as medicines and surgeries, in clinics, hospital wards, or operating rooms.","source":"https://www.onetonline.org/link/summary/29-1242.00"}],"knowledge":[],"skills":[],"abilities":[],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1242.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29124300","title":"Pediatric Surgeons","soc":"29-1243.00","summary":"Diagnose and perform surgery to treat fetal abnormalities and birth defects, diseases, and injuries in fetuses, premature and newborn infants, children, and adolescents. Includes all pediatric surgical specialties and subspecialties.","url":"https://www.onetonline.org/link/summary/29-1243.00","sourceURL":"https://www.onetonline.org/link/summary/29-1243.00","vector":[4.95,6.52,1.55,4.99,2.43,3.91],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Analyze patient's medical history, medication allergies, physical condition, and examination results to verify operation's necessity and to determine best procedure.","source":"https://www.onetonline.org/link/summary/29-1243.00"},{"text":"Conduct research to develop and test surgical techniques that can improve operating procedures and outcomes.","source":"https://www.onetonline.org/link/summary/29-1243.00"},{"text":"Consult with patient's other medical care specialists, such as cardiologist and endocrinologist, to determine if surgery is necessary.","source":"https://www.onetonline.org/link/summary/29-1243.00"}],"knowledge":[],"skills":[],"abilities":[],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1243.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29124900","title":"Surgeons, All Other","soc":"29-1249.00","summary":"All surgeons not listed separately.","url":"https://www.onetonline.org/link/summary/29-1249.00","sourceURL":"https://www.onetonline.org/link/summary/29-1249.00","vector":null,"expandedDegree":true,"fieldIds":["science"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Doctoral or professional degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":null,"tasks":[],"knowledge":[],"skills":[],"abilities":[],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1249.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29129100","title":"Acupuncturists","soc":"29-1291.00","summary":"Diagnose, treat, and prevent disorders by stimulating specific acupuncture points within the body using acupuncture needles. May also use cups, nutritional supplements, therapeutic massage, acupressure, and other alternative health therapies.","url":"https://www.onetonline.org/link/summary/29-1291.00","sourceURL":"https://www.onetonline.org/link/summary/29-1291.00","vector":[4.8,5.49,2.08,5.65,1.6,3.06],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Master's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Maintain and follow standard quality, safety, environmental, and infection control policies and procedures.","source":"https://www.onetonline.org/link/summary/29-1291.00"},{"text":"Treat patients using tools, such as needles, cups, ear balls, seeds, pellets, or nutritional supplements.","source":"https://www.onetonline.org/link/summary/29-1291.00"},{"text":"Adhere to local, state, and federal laws, regulations, and statutes.","source":"https://www.onetonline.org/link/summary/29-1291.00"}],"knowledge":["Customer and Personal Service","Medicine and Dentistry","Psychology","Biology"],"skills":["Active Listening","Critical Thinking","Service Orientation","Social Perceptiveness"],"abilities":["Deductive Reasoning","Near Vision","Oral Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1291.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29129900","title":"Healthcare Diagnosing or Treating Practitioners, All Other","soc":"29-1299.00","summary":"All healthcare diagnosing or treating practitioners not listed separately.","url":"https://www.onetonline.org/link/summary/29-1299.00","sourceURL":"https://www.onetonline.org/link/summary/29-1299.00","vector":null,"expandedDegree":true,"fieldIds":["science"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Master's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":null,"tasks":[],"knowledge":[],"skills":[],"abilities":[],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1299.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29129901","title":"Naturopathic Physicians","soc":"29-1299.01","summary":"Diagnose, treat, and help prevent diseases using a system of practice that is based on the natural healing capacity of individuals. May use physiological, psychological or mechanical methods. May also use natural medicines, prescription or legend drugs, foods, herbs, or other natural remedies.","url":"https://www.onetonline.org/link/summary/29-1299.01","sourceURL":"https://www.onetonline.org/link/summary/29-1299.01","vector":[4.53,5.89,1.81,5.73,1.98,3.25],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Master's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Document patients' histories, including identifying data, chief complaints, illnesses, previous medical or family histories, or psychosocial characteristics.","source":"https://www.onetonline.org/link/summary/29-1299.01"},{"text":"Educate patients about health care management.","source":"https://www.onetonline.org/link/summary/29-1299.01"},{"text":"Advise patients about therapeutic exercise and nutritional medicine regimens.","source":"https://www.onetonline.org/link/summary/29-1299.01"}],"knowledge":["Medicine and Dentistry","Biology","Psychology","Therapy and Counseling"],"skills":["Reading Comprehension","Active Listening","Critical Thinking","Speaking"],"abilities":["Problem Sensitivity","Deductive Reasoning","Inductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1299.01"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29129902","title":"Orthoptists","soc":"29-1299.02","summary":"Diagnose and treat visual system disorders such as binocular vision and eye movement impairments.","url":"https://www.onetonline.org/link/summary/29-1299.02","sourceURL":"https://www.onetonline.org/link/summary/29-1299.02","vector":[4.88,5.74,1.88,4.77,1.47,3.82],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Master's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Evaluate, diagnose, or treat disorders of the visual system with an emphasis on binocular vision or abnormal eye movements.","source":"https://www.onetonline.org/link/summary/29-1299.02"},{"text":"Examine patients with problems related to ocular motility, binocular vision, amblyopia, or strabismus.","source":"https://www.onetonline.org/link/summary/29-1299.02"},{"text":"Perform diagnostic tests or measurements, such as motor testing, visual acuity testing, lensometry, retinoscopy, and color vision testing.","source":"https://www.onetonline.org/link/summary/29-1299.02"}],"knowledge":["Medicine and Dentistry","Customer and Personal Service","English Language","Biology"],"skills":["Active Listening","Reading Comprehension","Critical Thinking","Speaking"],"abilities":["Problem Sensitivity","Deductive Reasoning","Inductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-1299.02"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29201100","title":"Medical and Clinical Laboratory Technologists","soc":"29-2011.00","summary":"Perform complex medical laboratory tests for diagnosis, treatment, and prevention of disease. May train or supervise staff.","url":"https://www.onetonline.org/link/summary/29-2011.00","sourceURL":"https://www.onetonline.org/link/summary/29-2011.00","vector":[5.81,6.15,1.13,2.77,1.51,4.99],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Analyze samples of biological material for chemical content or reaction.","source":"https://www.onetonline.org/link/summary/29-2011.00"},{"text":"Analyze laboratory findings to check the accuracy of the results.","source":"https://www.onetonline.org/link/summary/29-2011.00"},{"text":"Conduct chemical analysis of body fluids, including blood, urine, or spinal fluid, to determine presence of normal or abnormal components.","source":"https://www.onetonline.org/link/summary/29-2011.00"}],"knowledge":["Chemistry","Customer and Personal Service","Computers and Electronics","English Language"],"skills":["Critical Thinking","Science","Active Listening","Reading Comprehension"],"abilities":["Inductive Reasoning","Near Vision","Information Ordering"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-2011.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29201101","title":"Cytogenetic Technologists","soc":"29-2011.01","summary":"Analyze chromosomes or chromosome segments found in biological specimens, such as amniotic fluids, bone marrow, solid tumors, and blood to aid in the study, diagnosis, classification, or treatment of inherited or acquired genetic diseases. Conduct analyses through classical cytogenetic, fluorescent in situ hybridization (FISH) or array comparative genome hybridization (aCGH) techniques.","url":"https://www.onetonline.org/link/summary/29-2011.01","sourceURL":"https://www.onetonline.org/link/summary/29-2011.01","vector":[5.32,5.91,1.48,1.93,1.56,5.02],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Arrange and attach chromosomes in numbered pairs on karyotype charts, using standard genetics laboratory practices and nomenclature, to identify normal or abnormal chromosomes.","source":"https://www.onetonline.org/link/summary/29-2011.01"},{"text":"Analyze chromosomes found in biological specimens to aid diagnoses and treatments for genetic diseases such as congenital disabilities, fertility problems, and hematological disorders.","source":"https://www.onetonline.org/link/summary/29-2011.01"},{"text":"Prepare biological specimens such as amniotic fluids, bone marrow, tumors, chorionic villi, and blood, for chromosome examinations.","source":"https://www.onetonline.org/link/summary/29-2011.01"}],"knowledge":["Biology","Chemistry","English Language","Education and Training"],"skills":["Reading Comprehension","Critical Thinking","Active Listening","Speaking"],"abilities":["Inductive Reasoning","Information Ordering","Near Vision"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-2011.01"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29201102","title":"Cytotechnologists","soc":"29-2011.02","summary":"Stain, mount, and study cells to detect evidence of cancer, hormonal abnormalities, and other pathological conditions following established standards and practices.","url":"https://www.onetonline.org/link/summary/29-2011.02","sourceURL":"https://www.onetonline.org/link/summary/29-2011.02","vector":[5.92,6.06,1.1,2.41,1.84,4.89],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"college","jobZone":5,"tasks":[{"text":"Examine cell samples to detect abnormalities in the color, shape, or size of cellular components and patterns.","source":"https://www.onetonline.org/link/summary/29-2011.02"},{"text":"Document specimens by verifying patients' and specimens' information.","source":"https://www.onetonline.org/link/summary/29-2011.02"},{"text":"Submit slides with abnormal cell structures to pathologists for further examination.","source":"https://www.onetonline.org/link/summary/29-2011.02"}],"knowledge":["Biology","Medicine and Dentistry","English Language","Administrative"],"skills":["Reading Comprehension","Active Listening","Critical Thinking","Complex Problem Solving"],"abilities":["Near Vision","Oral Comprehension","Written Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-2011.02"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29201104","title":"Histotechnologists","soc":"29-2011.04","summary":"Apply knowledge of health and disease causes to evaluate new laboratory techniques and procedures to examine tissue samples. Process and prepare histological slides from tissue sections for microscopic examination and diagnosis by pathologists. May solve technical or instrument problems or assist with research studies.","url":"https://www.onetonline.org/link/summary/29-2011.04","sourceURL":"https://www.onetonline.org/link/summary/29-2011.04","vector":[5.72,6.56,1.31,2.89,1.05,5.16],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Embed tissue specimens into paraffin wax blocks, or infiltrate tissue specimens with wax.","source":"https://www.onetonline.org/link/summary/29-2011.04"},{"text":"Cut sections of body tissues for microscopic examination, using microtomes.","source":"https://www.onetonline.org/link/summary/29-2011.04"},{"text":"Stain tissue specimens with dyes or other chemicals to make cell details visible under microscopes.","source":"https://www.onetonline.org/link/summary/29-2011.04"}],"knowledge":["Biology","Production and Processing","Chemistry","Customer and Personal Service"],"skills":["Reading Comprehension","Critical Thinking","Monitoring","Judgment and Decision Making"],"abilities":["Near Vision","Written Comprehension","Arm-Hand Steadiness"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-2011.04"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29201200","title":"Medical and Clinical Laboratory Technicians","soc":"29-2012.00","summary":"Perform routine medical laboratory tests for the diagnosis, treatment, and prevention of disease. May work under the supervision of a medical technologist.","url":"https://www.onetonline.org/link/summary/29-2012.00","sourceURL":"https://www.onetonline.org/link/summary/29-2012.00","vector":[6.01,5.89,1,2.88,1,4.85],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"college","jobZone":3,"tasks":[{"text":"Perform quality control analyses to ensure accuracy of test results.","source":"https://www.onetonline.org/link/summary/29-2012.00"},{"text":"Conduct blood tests for transfusion purposes and perform blood counts.","source":"https://www.onetonline.org/link/summary/29-2012.00"},{"text":"Conduct chemical analyses of body fluids, such as blood or urine, using microscope or automatic analyzer to detect abnormalities or diseases and enter findings into computer.","source":"https://www.onetonline.org/link/summary/29-2012.00"}],"knowledge":["Chemistry","English Language","Biology","Medicine and Dentistry"],"skills":["Reading Comprehension","Active Listening","Critical Thinking","Operations Monitoring"],"abilities":["Near Vision","Information Ordering","Oral Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-2012.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29201201","title":"Histology Technicians","soc":"29-2012.01","summary":"Prepare histological slides from tissue sections for microscopic examination and diagnosis by pathologists. May assist with research studies.","url":"https://www.onetonline.org/link/summary/29-2012.01","sourceURL":"https://www.onetonline.org/link/summary/29-2012.01","vector":[6.29,5.37,1.26,2.12,1,5.03],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"college","jobZone":3,"tasks":[{"text":"Cut sections of body tissues for microscopic examination, using microtomes.","source":"https://www.onetonline.org/link/summary/29-2012.01"},{"text":"Embed tissue specimens into paraffin wax blocks, or infiltrate tissue specimens with wax.","source":"https://www.onetonline.org/link/summary/29-2012.01"},{"text":"Mount tissue specimens on glass slides.","source":"https://www.onetonline.org/link/summary/29-2012.01"}],"knowledge":["Chemistry","Biology","English Language","Administrative"],"skills":["Active Listening","Critical Thinking","Reading Comprehension","Monitoring"],"abilities":["Near Vision","Finger Dexterity","Oral Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-2012.01"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29203600","title":"Medical Dosimetrists","soc":"29-2036.00","summary":"Generate radiation treatment plans, develop radiation dose calculations, communicate and supervise the treatment plan implementation, and consult with members of radiation oncology team.","url":"https://www.onetonline.org/link/summary/29-2036.00","sourceURL":"https://www.onetonline.org/link/summary/29-2036.00","vector":[4.57,5.3,1.32,3.57,2.21,5],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Design the arrangement of radiation fields to reduce exposure to critical patient structures, such as organs, using computers, manuals, and guides.","source":"https://www.onetonline.org/link/summary/29-2036.00"},{"text":"Plan the use of beam modifying devices, such as compensators, shields, and wedge filters, to ensure safe and effective delivery of radiation treatment.","source":"https://www.onetonline.org/link/summary/29-2036.00"},{"text":"Identify and outline bodily structures, using imaging procedures, such as x-ray, magnetic resonance imaging, computed tomography, or positron emission tomography.","source":"https://www.onetonline.org/link/summary/29-2036.00"}],"knowledge":["Mathematics","Physics","Computers and Electronics","Biology"],"skills":["Critical Thinking","Active Listening","Reading Comprehension","Speaking"],"abilities":["Deductive Reasoning","Inductive Reasoning","Written Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-2036.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29209100","title":"Orthotists and Prosthetists","soc":"29-2091.00","summary":"Design, measure, fit, and adapt orthopedic braces, appliances or prostheses, such as limbs or facial parts for patients with disabling conditions.","url":"https://www.onetonline.org/link/summary/29-2091.00","sourceURL":"https://www.onetonline.org/link/summary/29-2091.00","vector":[6,5.1,1.99,4.3,1.56,3.58],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Master's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Fit, test, and evaluate devices on patients, and make adjustments for proper fit, function, and comfort.","source":"https://www.onetonline.org/link/summary/29-2091.00"},{"text":"Instruct patients in the use and care of orthoses and prostheses.","source":"https://www.onetonline.org/link/summary/29-2091.00"},{"text":"Maintain patients' records.","source":"https://www.onetonline.org/link/summary/29-2091.00"}],"knowledge":["Customer and Personal Service","Medicine and Dentistry","Design","Therapy and Counseling"],"skills":["Active Listening","Critical Thinking","Reading Comprehension","Speaking"],"abilities":["Deductive Reasoning","Inductive Reasoning","Near Vision"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-2091.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29909100","title":"Athletic Trainers","soc":"29-9091.00","summary":"Evaluate and treat musculoskeletal injuries or illnesses. Provide preventive, therapeutic, emergency, and rehabilitative care.","url":"https://www.onetonline.org/link/summary/29-9091.00","sourceURL":"https://www.onetonline.org/link/summary/29-9091.00","vector":[5.63,4.4,1.15,5.75,2.24,3.22],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Master's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Conduct an initial assessment of an athlete's injury or illness to provide emergency or continued care and to determine whether they should be referred to physicians for definitive diagnosis and treatment.","source":"https://www.onetonline.org/link/summary/29-9091.00"},{"text":"Assess and report the progress of recovering athletes to coaches or physicians.","source":"https://www.onetonline.org/link/summary/29-9091.00"},{"text":"Care for athletic injuries, using physical therapy equipment, techniques, or medication.","source":"https://www.onetonline.org/link/summary/29-9091.00"}],"knowledge":["Medicine and Dentistry","Customer and Personal Service","Psychology","Therapy and Counseling"],"skills":["Active Listening","Critical Thinking","Monitoring","Speaking"],"abilities":["Problem Sensitivity","Oral Expression","Speech Clarity"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-9091.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-29909200","title":"Genetic Counselors","soc":"29-9092.00","summary":"Assess individual or family risk for a variety of inherited conditions, such as genetic disorders and birth defects. Provide information to other healthcare providers or to individuals and families concerned with the risk of inherited conditions. Advise individuals and families to support informed decisionmaking and coping methods for those at risk. May help conduct research related to genetic conditions or genetic counseling.","url":"https://www.onetonline.org/link/summary/29-9092.00","sourceURL":"https://www.onetonline.org/link/summary/29-9092.00","vector":[1.66,5.86,2.34,5.45,2.73,3.89],"expandedDegree":true,"fieldIds":["health"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Master's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"graduate","jobZone":5,"tasks":[{"text":"Provide counseling to patient and family members by providing information, education, or reassurance.","source":"https://www.onetonline.org/link/summary/29-9092.00"},{"text":"Analyze genetic information to identify patients or families at risk for specific disorders or syndromes.","source":"https://www.onetonline.org/link/summary/29-9092.00"},{"text":"Provide genetic counseling in specified areas of clinical genetics, such as obstetrics, pediatrics, oncology and neurology.","source":"https://www.onetonline.org/link/summary/29-9092.00"}],"knowledge":["Biology","Therapy and Counseling","English Language","Medicine and Dentistry"],"skills":["Active Listening","Reading Comprehension","Active Learning","Critical Thinking"],"abilities":["Oral Comprehension","Oral Expression","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/29-9092.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-33303100","title":"Fish and Game Wardens","soc":"33-3031.00","summary":"Patrol assigned area to prevent fish and game law violations. Investigate reports of damage to crops or property by wildlife. Compile biological data.","url":"https://www.onetonline.org/link/summary/33-3031.00","sourceURL":"https://www.onetonline.org/link/summary/33-3031.00","vector":[6.4,3.91,1,2.38,3.02,4.24],"expandedDegree":true,"fieldIds":["public-safety"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"college","jobZone":3,"tasks":[{"text":"Participate in search-and-rescue operations.","source":"https://www.onetonline.org/link/summary/33-3031.00"},{"text":"Compile and present evidence for court actions.","source":"https://www.onetonline.org/link/summary/33-3031.00"},{"text":"Protect and preserve native wildlife, plants, or ecosystems.","source":"https://www.onetonline.org/link/summary/33-3031.00"}],"knowledge":["Public Safety and Security","Law and Government","Customer and Personal Service","English Language"],"skills":["Speaking","Active Listening","Critical Thinking","Reading Comprehension"],"abilities":["Deductive Reasoning","Inductive Reasoning","Oral Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/33-3031.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-41303100","title":"Securities, Commodities, and Financial Services Sales Agents","soc":"41-3031.00","summary":"Buy and sell securities or commodities in investment and trading firms, or provide financial services to businesses and individuals. May advise customers about stocks, bonds, mutual funds, commodities, and market conditions.","url":"https://www.onetonline.org/link/summary/41-3031.00","sourceURL":"https://www.onetonline.org/link/summary/41-3031.00","vector":[1.26,2.53,1.29,3.07,6.08,5.27],"expandedDegree":true,"fieldIds":["sales-office"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Make bids or offers to buy or sell securities.","source":"https://www.onetonline.org/link/summary/41-3031.00"},{"text":"Monitor markets or positions.","source":"https://www.onetonline.org/link/summary/41-3031.00"},{"text":"Agree on buying or selling prices at optimal levels for clients.","source":"https://www.onetonline.org/link/summary/41-3031.00"}],"knowledge":["Customer and Personal Service","Economics and Accounting","English Language","Mathematics"],"skills":["Active Listening","Critical Thinking","Monitoring","Judgment and Decision Making"],"abilities":["Oral Comprehension","Oral Expression","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/41-3031.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-41401100","title":"Sales Representatives, Wholesale and Manufacturing, Technical and Scientific Products","soc":"41-4011.00","summary":"Sell goods for wholesalers or manufacturers where technical or scientific knowledge is required in such areas as biology, engineering, chemistry, and electronics, normally obtained from at least 2 years of postsecondary education.","url":"https://www.onetonline.org/link/summary/41-4011.00","sourceURL":"https://www.onetonline.org/link/summary/41-4011.00","vector":[2.8,3.15,1.44,3.12,5.27,5.14],"expandedDegree":true,"fieldIds":["sales-office"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Negotiate prices or terms of sales or service agreements.","source":"https://www.onetonline.org/link/summary/41-4011.00"},{"text":"Prepare and submit sales contracts for orders.","source":"https://www.onetonline.org/link/summary/41-4011.00"},{"text":"Visit establishments to evaluate needs or to promote product or service sales.","source":"https://www.onetonline.org/link/summary/41-4011.00"}],"knowledge":["Customer and Personal Service","Sales and Marketing","English Language","Administration and Management"],"skills":["Speaking","Persuasion","Active Listening","Negotiation"],"abilities":["Oral Expression","Oral Comprehension","Speech Clarity"],"sources":[{"url":"https://www.onetonline.org/link/summary/41-4011.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-41401107","title":"Solar Sales Representatives and Assessors","soc":"41-4011.07","summary":"Contact new or existing customers to determine their solar equipment needs, suggest systems or equipment, or estimate costs.","url":"https://www.onetonline.org/link/summary/41-4011.07","sourceURL":"https://www.onetonline.org/link/summary/41-4011.07","vector":[3.52,2.73,1.39,2.75,5.56,4.43],"expandedDegree":true,"fieldIds":["sales-office"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"broader BLS SOC; O*NET specialty is distinct"},"educationGroup":"college","jobZone":3,"tasks":[{"text":"Prepare proposals, quotes, contracts, or presentations for potential solar customers.","source":"https://www.onetonline.org/link/summary/41-4011.07"},{"text":"Select solar energy products, systems, or services for customers based on electrical energy requirements, site conditions, price, or other factors.","source":"https://www.onetonline.org/link/summary/41-4011.07"},{"text":"Provide customers with information, such as quotes, orders, sales, shipping, warranties, credit, funding options, incentives, or tax rebates.","source":"https://www.onetonline.org/link/summary/41-4011.07"}],"knowledge":["Customer and Personal Service","Sales and Marketing","Design","English Language"],"skills":["Speaking","Reading Comprehension","Persuasion","Service Orientation"],"abilities":["Oral Comprehension","Oral Expression","Speech Clarity"],"sources":[{"url":"https://www.onetonline.org/link/summary/41-4011.07"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-41903100","title":"Sales Engineers","soc":"41-9031.00","summary":"Sell business goods or services, the selling of which requires a technical background equivalent to a baccalaureate degree in engineering.","url":"https://www.onetonline.org/link/summary/41-9031.00","sourceURL":"https://www.onetonline.org/link/summary/41-9031.00","vector":[3.38,3.58,1.76,2.82,5.78,4.51],"expandedDegree":true,"fieldIds":["sales-office"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Sell products requiring extensive technical expertise and support for installation and use, such as material handling equipment, numerical-control machinery, or computer systems.","source":"https://www.onetonline.org/link/summary/41-9031.00"},{"text":"Develop, present, or respond to proposals for specific customer requirements, including request for proposal responses and industry-specific solutions.","source":"https://www.onetonline.org/link/summary/41-9031.00"},{"text":"Collaborate with sales teams to understand customer requirements, to promote the sale of company products, and to provide sales support.","source":"https://www.onetonline.org/link/summary/41-9031.00"}],"knowledge":["Customer and Personal Service","Sales and Marketing","Engineering and Technology","English Language"],"skills":["Speaking","Persuasion","Active Listening","Critical Thinking"],"abilities":["Oral Expression","Speech Clarity","Deductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/41-9031.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-43908100","title":"Proofreaders and Copy Markers","soc":"43-9081.00","summary":"Read transcript or proof type setup to detect and mark for correction any grammatical, typographical, or compositional errors. Excludes workers whose primary duty is editing copy. Includes proofreaders of braille.","url":"https://www.onetonline.org/link/summary/43-9081.00","sourceURL":"https://www.onetonline.org/link/summary/43-9081.00","vector":[1.44,2.5,3.56,2.2,1.53,6.16],"expandedDegree":true,"fieldIds":["sales-office"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Mark copy to indicate and correct errors in type, arrangement, grammar, punctuation, or spelling, using standard printers' marks.","source":"https://www.onetonline.org/link/summary/43-9081.00"},{"text":"Read corrected copies or proofs to ensure that all corrections have been made.","source":"https://www.onetonline.org/link/summary/43-9081.00"},{"text":"Correct or record omissions, errors, or inconsistencies found.","source":"https://www.onetonline.org/link/summary/43-9081.00"}],"knowledge":["English Language","Communications and Media","Computers and Electronics","Administrative"],"skills":["Reading Comprehension","Writing","Speaking","Active Listening"],"abilities":["Written Comprehension","Near Vision","Oral Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/43-9081.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-43911100","title":"Statistical Assistants","soc":"43-9111.00","summary":"Compile and compute data according to statistical formulas for use in statistical studies. May perform actuarial computations and compile charts and graphs for use by actuaries. Includes actuarial clerks.","url":"https://www.onetonline.org/link/summary/43-9111.00","sourceURL":"https://www.onetonline.org/link/summary/43-9111.00","vector":[2.37,4.48,1,1.4,1.74,7],"expandedDegree":true,"fieldIds":["sales-office"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Compute and analyze data, using statistical formulas and computers or calculators.","source":"https://www.onetonline.org/link/summary/43-9111.00"},{"text":"Present results of statistical analyses to stakeholders.","source":"https://www.onetonline.org/link/summary/43-9111.00"},{"text":"File data and related information, and maintain and update databases.","source":"https://www.onetonline.org/link/summary/43-9111.00"}],"knowledge":["Mathematics","English Language","Computers and Electronics","Administrative"],"skills":["Mathematics","Critical Thinking","Reading Comprehension","Active Learning"],"abilities":["Mathematical Reasoning","Number Facility","Written Comprehension"],"sources":[{"url":"https://www.onetonline.org/link/summary/43-9111.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-45201100","title":"Agricultural Inspectors","soc":"45-2011.00","summary":"Inspect agricultural commodities, processing equipment, and facilities, and fish and logging operations, to ensure compliance with regulations and laws governing health, quality, and safety.","url":"https://www.onetonline.org/link/summary/45-2011.00","sourceURL":"https://www.onetonline.org/link/summary/45-2011.00","vector":[5.35,4.04,1,1.89,3.12,5.17],"expandedDegree":true,"fieldIds":["science"],"pathIds":[],"requiresExperience":false,"experience":"None","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"college","jobZone":2,"tasks":[{"text":"Inspect food products and processing procedures to determine whether products are safe to eat.","source":"https://www.onetonline.org/link/summary/45-2011.00"},{"text":"Monitor the operations and sanitary conditions of slaughtering or meat processing plants.","source":"https://www.onetonline.org/link/summary/45-2011.00"},{"text":"Label and seal graded products and issue official grading certificates.","source":"https://www.onetonline.org/link/summary/45-2011.00"}],"knowledge":["Customer and Personal Service","Administration and Management","Law and Government","Administrative"],"skills":["Quality Control Analysis","Active Listening","Monitoring","Reading Comprehension"],"abilities":["Problem Sensitivity","Deductive Reasoning","Inductive Reasoning"],"sources":[{"url":"https://www.onetonline.org/link/summary/45-2011.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null},{"id":"degree-53201100","title":"Airline Pilots, Copilots, and Flight Engineers","soc":"53-2011.00","summary":"Pilot and navigate the flight of fixed-wing aircraft, usually on scheduled air carrier routes, for the transport of passengers and cargo. Requires Federal Air Transport certificate and rating for specific aircraft type used. Includes regional, national, and international airline pilots and flight instructors of airline pilots.","url":"https://www.onetonline.org/link/summary/53-2011.00","sourceURL":"https://www.onetonline.org/link/summary/53-2011.00","vector":[4.74,3.15,1.44,2.5,3.81,4.7],"expandedDegree":true,"fieldIds":["transportation-production"],"pathIds":[],"requiresExperience":true,"experience":"Less than 5 years","preparation":{"typicalEducation":["Bachelor's degree"],"sourceURL":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm","mapping":"exact detailed SOC"},"educationGroup":"college","jobZone":4,"tasks":[{"text":"Use instrumentation to guide flights when visibility is poor.","source":"https://www.onetonline.org/link/summary/53-2011.00"},{"text":"Start engines, operate controls, and pilot airplanes to transport passengers, mail, or freight, adhering to flight plans, regulations, and procedures.","source":"https://www.onetonline.org/link/summary/53-2011.00"},{"text":"Work as part of a flight team with other crew members, especially during takeoffs and landings.","source":"https://www.onetonline.org/link/summary/53-2011.00"}],"knowledge":["Transportation","English Language","Public Safety and Security","Geography"],"skills":["Operation and Control","Operations Monitoring","Active Listening","Critical Thinking"],"abilities":["Response Orientation","Problem Sensitivity","Control Precision"],"sources":[{"url":"https://www.onetonline.org/link/summary/53-2011.00"},{"url":"https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm"}],"relatedIds":[],"finance":null}];
